import{_ as s,o as e,c as t,a2 as n}from"./chunks/framework.DcI5CFgX.js";const h=JSON.parse('{"title":"附录I Appendix I","description":"","frontmatter":{},"headers":[],"relativePath":"content/附录I.md","filePath":"content/附录I.md","lastUpdated":1793989180000}'),o={name:"content/附录I.md"};function p(l,a,i,r,u,c){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="附录i-appendix-i" tabindex="-1">附录I Appendix I <a class="header-anchor" href="#附录i-appendix-i" aria-label="Permalink to &quot;附录I Appendix I&quot;">​</a></h1><blockquote><p>Here is a complete grammar for Lox. The chapters that introduce each part of the language include the grammar rules there, but this collects them all into one place.</p></blockquote><p>这里有一份Lox的完整语法。介绍语言每个部分的章节中都包含对应的语法规则，但这里将它们全部收录在一起了。</p><blockquote><h2 id="a1-1-syntax-grammar" tabindex="-1">A1 . 1 Syntax Grammar <a class="header-anchor" href="#a1-1-syntax-grammar" aria-label="Permalink to &quot;A1 . 1 Syntax Grammar&quot;">​</a></h2></blockquote><h2 id="a1-1-语法" tabindex="-1">A1.1 语法 <a class="header-anchor" href="#a1-1-语法" aria-label="Permalink to &quot;A1.1 语法&quot;">​</a></h2><blockquote><p>The syntactic grammar is used to parse the linear sequence of tokens into the nested syntax tree structure. It starts with the first rule that matches an entire Lox program (or a single REPL entry).</p></blockquote><p>语法用于将词法标识（token）的线性序列解析为嵌套的语法树结构。它从匹配整个Lox程序（或单条REPL输入）的第一个规则开始。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>program        → declaration* EOF ;</span></span></code></pre></div><blockquote><h3 id="a1-1-1-declarations" tabindex="-1">A1 . 1 . 1 Declarations <a class="header-anchor" href="#a1-1-1-declarations" aria-label="Permalink to &quot;A1 . 1 . 1 Declarations&quot;">​</a></h3></blockquote><h3 id="a1-1-1-声明" tabindex="-1">A1.1.1 声明 <a class="header-anchor" href="#a1-1-1-声明" aria-label="Permalink to &quot;A1.1.1 声明&quot;">​</a></h3><blockquote><p>A program is a series of declarations, which are the statements that bind new identifiers or any of the other statement types.</p></blockquote><p>一个程序就是一系列的声明，也就是绑定新标识符或其它statement类型的语句。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>declaration    → classDecl</span></span>
<span class="line"><span>               | funDecl</span></span>
<span class="line"><span>               | varDecl</span></span>
<span class="line"><span>               | statement ;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>classDecl      → &quot;class&quot; IDENTIFIER ( &quot;&lt;&quot; IDENTIFIER )?</span></span>
<span class="line"><span>                 &quot;{&quot; function* &quot;}&quot; ;</span></span>
<span class="line"><span>funDecl        → &quot;fun&quot; function ;</span></span>
<span class="line"><span>varDecl        → &quot;var&quot; IDENTIFIER ( &quot;=&quot; expression )? &quot;;&quot; ;</span></span></code></pre></div><blockquote><h3 id="a1-1-2-statements" tabindex="-1">A1 . 1 . 2 Statements <a class="header-anchor" href="#a1-1-2-statements" aria-label="Permalink to &quot;A1 . 1 . 2 Statements&quot;">​</a></h3></blockquote><h3 id="a1-1-2-语句" tabindex="-1">A1.1.2 语句 <a class="header-anchor" href="#a1-1-2-语句" aria-label="Permalink to &quot;A1.1.2 语句&quot;">​</a></h3><blockquote><p>The remaining statement rules produce side effects, but do not introduce bindings.</p></blockquote><p>其余的语句规则会产生副作用，但不会引入绑定。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>statement      → exprStmt</span></span>
<span class="line"><span>               | forStmt</span></span>
<span class="line"><span>               | ifStmt</span></span>
<span class="line"><span>               | printStmt</span></span>
<span class="line"><span>               | returnStmt</span></span>
<span class="line"><span>               | whileStmt</span></span>
<span class="line"><span>               | block ;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>exprStmt       → expression &quot;;&quot; ;</span></span>
<span class="line"><span>forStmt        → &quot;for&quot; &quot;(&quot; ( varDecl | exprStmt | &quot;;&quot; )</span></span>
<span class="line"><span>                           expression? &quot;;&quot;</span></span>
<span class="line"><span>                           expression? &quot;)&quot; statement ;</span></span>
<span class="line"><span>ifStmt         → &quot;if&quot; &quot;(&quot; expression &quot;)&quot; statement</span></span>
<span class="line"><span>                 ( &quot;else&quot; statement )? ;</span></span>
<span class="line"><span>printStmt      → &quot;print&quot; expression &quot;;&quot; ;</span></span>
<span class="line"><span>returnStmt     → &quot;return&quot; expression? &quot;;&quot; ;</span></span>
<span class="line"><span>whileStmt      → &quot;while&quot; &quot;(&quot; expression &quot;)&quot; statement ;</span></span>
<span class="line"><span>block          → &quot;{&quot; declaration* &quot;}&quot; ;</span></span></code></pre></div><blockquote><p>Note that <code>block</code> is a statement rule, but is also used as a nonterminal in a couple of other rules for things like function bodies.</p></blockquote><p>请注意，<code>block</code>是一个语句规则，但在其它规则中也作为非终止符使用，用于表示函数体等内容。</p><blockquote><h3 id="a1-1-3-expressions" tabindex="-1">A1 . 1 . 3 Expressions <a class="header-anchor" href="#a1-1-3-expressions" aria-label="Permalink to &quot;A1 . 1 . 3 Expressions&quot;">​</a></h3></blockquote><h3 id="a1-1-3-表达式" tabindex="-1">A1.1.3 表达式 <a class="header-anchor" href="#a1-1-3-表达式" aria-label="Permalink to &quot;A1.1.3 表达式&quot;">​</a></h3><blockquote><p>Expressions produce values. Lox has a number of unary and binary operators with different levels of precedence. Some grammars for languages do not directly encode the precedence relationships and specify that elsewhere. Here, we use a separate rule for each precedence level to make it explicit.</p></blockquote><p>表达式会产生值。Lox有许多具有不同优先级的一元或二元运算符。一些语言的语法中没有直接编码优先级关系，而是在其它地方指定。在这里，我们为每个优先级使用单独的规则，使其明确。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>expression     → assignment ;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>assignment     → ( call &quot;.&quot; )? IDENTIFIER &quot;=&quot; assignment</span></span>
<span class="line"><span>               | logic_or ;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>logic_or       → logic_and ( &quot;or&quot; logic_and )* ;</span></span>
<span class="line"><span>logic_and      → equality ( &quot;and&quot; equality )* ;</span></span>
<span class="line"><span>equality       → comparison ( ( &quot;!=&quot; | &quot;==&quot; ) comparison )* ;</span></span>
<span class="line"><span>comparison     → term ( ( &quot;&gt;&quot; | &quot;&gt;=&quot; | &quot;&lt;&quot; | &quot;&lt;=&quot; ) term )* ;</span></span>
<span class="line"><span>term           → factor ( ( &quot;-&quot; | &quot;+&quot; ) factor )* ;</span></span>
<span class="line"><span>factor         → unary ( ( &quot;/&quot; | &quot;*&quot; ) unary )* ;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>unary          → ( &quot;!&quot; | &quot;-&quot; ) unary | call ;</span></span>
<span class="line"><span>call           → primary ( &quot;(&quot; arguments? &quot;)&quot; | &quot;.&quot; IDENTIFIER )* ;</span></span>
<span class="line"><span>primary        → &quot;true&quot; | &quot;false&quot; | &quot;nil&quot; | &quot;this&quot;</span></span>
<span class="line"><span>               | NUMBER | STRING | IDENTIFIER | &quot;(&quot; expression &quot;)&quot;</span></span>
<span class="line"><span>               | &quot;super&quot; &quot;.&quot; IDENTIFIER ;</span></span></code></pre></div><blockquote><h3 id="a1-1-4-utility-rules" tabindex="-1">A1 . 1 . 4 Utility rules <a class="header-anchor" href="#a1-1-4-utility-rules" aria-label="Permalink to &quot;A1 . 1 . 4 Utility rules&quot;">​</a></h3></blockquote><h3 id="a1-1-4-实用规则" tabindex="-1">A1.1.4 实用规则 <a class="header-anchor" href="#a1-1-4-实用规则" aria-label="Permalink to &quot;A1.1.4 实用规则&quot;">​</a></h3><blockquote><p>In order to keep the above rules a little cleaner, some of the grammar is split out into a few reused helper rules.</p></blockquote><p>为了使上面的规则更简洁一点，一些语法被拆分为几个重复使用的辅助规则。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function       → IDENTIFIER &quot;(&quot; parameters? &quot;)&quot; block ;</span></span>
<span class="line"><span>parameters     → IDENTIFIER ( &quot;,&quot; IDENTIFIER )* ;</span></span>
<span class="line"><span>arguments      → expression ( &quot;,&quot; expression )* ;</span></span></code></pre></div><blockquote><h2 id="a1-2-lexical-grammar" tabindex="-1">A1 . 2 Lexical Grammar <a class="header-anchor" href="#a1-2-lexical-grammar" aria-label="Permalink to &quot;A1 . 2 Lexical Grammar&quot;">​</a></h2></blockquote><h2 id="a1-2-词法" tabindex="-1">A1.2 词法 <a class="header-anchor" href="#a1-2-词法" aria-label="Permalink to &quot;A1.2 词法&quot;">​</a></h2><blockquote><p>The lexical grammar is used by the scanner to group characters into tokens. Where the syntax is <a href="https://en.wikipedia.org/wiki/Context-free_grammar" target="_blank" rel="noreferrer">context free</a>, the lexical grammar is <a href="https://en.wikipedia.org/wiki/Regular_grammar" target="_blank" rel="noreferrer">regular</a>—note that there are no recursive rules.</p></blockquote><p>词法被扫描器用来将字符分组为词法标识（token）。语法是<a href="https://en.wikipedia.org/wiki/Context-free_grammar" target="_blank" rel="noreferrer">上下文无关</a>的，词法是<a href="https://en.wikipedia.org/wiki/Regular_grammar" target="_blank" rel="noreferrer">正则</a>的——注意这里没有递归规则。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NUMBER         → DIGIT+ ( &quot;.&quot; DIGIT+ )? ;</span></span>
<span class="line"><span>STRING         → &quot;\\&quot;&quot; &lt;any char except &quot;\\&quot;&quot;&gt;* &quot;\\&quot;&quot; ;</span></span>
<span class="line"><span>IDENTIFIER     → ALPHA ( ALPHA | DIGIT )* ;</span></span>
<span class="line"><span>ALPHA          → &quot;a&quot; ... &quot;z&quot; | &quot;A&quot; ... &quot;Z&quot; | &quot;_&quot; ;</span></span>
<span class="line"><span>DIGIT          → &quot;0&quot; ... &quot;9&quot; ;</span></span></code></pre></div>`,35)])])}const d=s(o,[["render",p]]);export{h as __pageData,d as default};
